addon.localeData.deDE.texts = {
    POWER_WORD_FORTITUDE = { gruppe = { "Steh aufrecht. Deine Zuversicht ist stärker als dein Zweifel.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Steh aufrecht. Deine Zuversicht ist stärker als dein Zweifel.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    POWER_WORD_SHIELD = { gruppe = { "Manchmal ist ein Augenblick Sicherheit das größte Wunder.", "Noch ein Schlag mag kommen. Dieses Licht wird ihn empfangen.", "*legt zwei Finger an das Handgelenk und spannt einen goldenen Schutzbogen auf.*", "*prüft die schimmernde Barriere mit einer ruhigen Handbewegung.*" }, ziel = { "Manchmal ist ein Augenblick Sicherheit das größte Wunder.", "%s, dieser Schutz gibt Euch den Augenblick, den Ihr braucht.", "*legt zwei Finger an das Handgelenk und spannt einen goldenen Schutzbogen auf.*", "*prüft die schimmernde Barriere mit einer ruhigen Handbewegung.*" }, },
    CONFOUNDING_FLASH = { gruppe = { "Ein Funke Verwirrung ist manchmal die klügste Antwort.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    STARSHARDS = { gruppe = { "Die Sterne haben lange geschwiegen. Jetzt antworten sie.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Die Sterne haben lange geschwiegen. Jetzt antworten sie.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    INNER_FIRE = { gruppe = { "Eine kleine Flamme genügt, um den Winter zu verachten.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    DISPEL_MAGIC = { gruppe = { "Fremder Zauber, deine Zeit ist abgelaufen.", "Nicht jede fremde Magie verdient ein Zuhause in dieser Welt.", "*greift nach einem unsichtbaren Faden und löst ihn aus dem Zaubergeflecht.*", "*streicht mit der offenen Hand die letzten fremden Funken fort.*" }, },
    CONTINGENCY_PLAN = { gruppe = { "Ich vertraue auf das Licht, aber ich plane für das Gegenteil.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Ich vertraue auf das Licht, aber ich plane für das Gegenteil.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    ELUNES_GRACE = { gruppe = { "Elune, lass mich zwischen den Schlägen hindurchschreiten.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    FEEDBACK = { gruppe = { "Wer meine Gedanken berührt, findet einen Spiegel aus Dornen.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    SHACKLE_UNDEAD = { gruppe = { "Ruhig, verlorene Seele. Dein Weg endet für einen Moment hier.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Ruhig, verlorene Seele. Dein Weg endet für einen Moment hier.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    MANA_BURN = { gruppe = { "Eure Magie knistert so laut, dass ich sie beinahe bedauere.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Eure Magie knistert so laut, dass ich sie beinahe bedauere.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    DIVINE_SPIRIT = { gruppe = { "Deine Gedanken brauchen keinen Käfig. Nur einen festen Anker.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, ziel = { "Deine Gedanken brauchen keinen Käfig. Nur einen festen Anker.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    PENANCE = { gruppe = { "Ein Urteil kann Wunde und Verband zugleich sein.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    LEVITATE = { gruppe = { "Der Boden darf mich später zurückhaben.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    PRAYER_OF_FORTITUDE = { gruppe = { "Möge niemand von uns heute den Mut verlieren.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    PRAYER_OF_SPIRIT = { gruppe = { "Wir atmen getrennt, doch hoffen gemeinsam.", "Gewissheit braucht keinen Lärm, nur einen festen Willen.", "*zieht eine klare Rune in die Luft*", "*legt zwei Finger an die Stirn und sammelt sich*" }, },
    INNER_FOCUS = { gruppe = { "Alle Stimmen verstummen. Eine Absicht bleibt.", "Kein Zweifel, kein Nebengeräusch. Nur noch der nächste Atemzug.", "*schließt die Augen und legt die Hände ruhig übereinander.*", "*atmet einmal tief ein, bis das Licht um die Fingerspitzen stillsteht.*" }, },
    POWER_INFUSION = { gruppe = { "Nimm diese Kraft. Und mach etwas Gutes daraus.", "Ich reiche Euch nicht nur Kraft, sondern mein Vertrauen.", "*führt einen leuchtenden Strom von der eigenen Hand zum Verbündeten.*", "*öffnet die Finger, als gäbe ein gespanntes Band seine Energie frei.*" }, ziel = { "Nimm diese Kraft. Und mach etwas Gutes daraus.", "%s, nehmt diese Kraft und setzt sie mit Bedacht ein.", "*führt einen leuchtenden Strom von der eigenen Hand zum Verbündeten.*", "*öffnet die Finger, als gäbe ein gespanntes Band seine Energie frei.*" }, },
    LESSER_HEAL = { gruppe = { "Nicht jede Wunde braucht ein Wunder, manche nur Geduld.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Nicht jede Wunde braucht ein Wunder, manche nur Geduld.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    SMITE = { gruppe = { "Das Licht kann sanft sein. Heute hat es andere Pläne.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Das Licht kann sanft sein. Heute hat es andere Pläne.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    RENEW = { gruppe = { "Heilung ist kein Augenblick. Sie ist ein Versprechen.", "Mit jedem Atemzug findet der Körper ein Stück seiner Kraft zurück.", "*legt die Fingerspitzen über die Verletzung und lässt kleine Lichtpunkte aufsteigen.*", "*zeichnet einen langsamen Kreis über dem Verband, bis der Schein nachklingt.*" }, ziel = { "Heilung ist kein Augenblick. Sie ist ein Versprechen.", "%s, die Heilung wirkt weiter. Gebt ihr ein wenig Zeit.", "*legt die Fingerspitzen über die Verletzung und lässt kleine Lichtpunkte aufsteigen.*", "*zeichnet einen langsamen Kreis über dem Verband, bis der Schein nachklingt.*" }, },
    DESPERATE_PRAYER = { gruppe = { "Wenn Worte versagen, bleibt ein letztes Gebet.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    DIVINE_GRACE = { gruppe = { "Nicht jetzt. Dieses Leben ist noch nicht zu Ende erzählt.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Nicht jetzt. Dieses Leben ist noch nicht zu Ende erzählt.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    RESURRECTION = { gruppe = { "Die Geschichte ist noch nicht zu Ende. Hörst du mich?", "Das Licht erreicht selbst jene, die unsere Stimme nicht mehr hören.", "*kniet neben dem reglosen Körper und legt beide Hände behutsam darüber.*", "*hält das heilige Symbol still, bis ein erster warmer Schimmer aufsteigt.*" }, ziel = { "Die Geschichte ist noch nicht zu Ende. Hörst du mich?", "%s, kehrt zu uns zurück. Euer Platz ist noch nicht leer.", "*kniet neben dem reglosen Körper und legt beide Hände behutsam darüber.*", "*hält das heilige Symbol still, bis ein erster warmer Schimmer aufsteigt.*" }, },
    CURE_DISEASE = { gruppe = { "Was sich eingeschlichen hat, darf wieder gehen.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Was sich eingeschlichen hat, darf wieder gehen.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    HEAL = { gruppe = { "Atme. Der nächste Schritt gehört dir.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Atme. Der nächste Schritt gehört dir.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    CHASTISE = { gruppe = { "Ein Wort genügt, wenn man es mit Überzeugung spricht.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Ein Wort genügt, wenn man es mit Überzeugung spricht.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    FEAR_WARD = { gruppe = { "Dein Mut ist dein eigener. Ich bewahre ihn nur.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Dein Mut ist dein eigener. Ich bewahre ihn nur.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    FLASH_HEAL = { gruppe = { "Keine Zeit für Predigten. Bleib bei uns!", "Jetzt zählt jede Sekunde. Das Gebet muss genügen.", "*stößt die Hand rasch vor, sodass ein kurzer Lichtimpuls aufflammt.*", "*fängt den eigenen Atem wieder ein, während das Licht schon wirkt.*" }, ziel = { "Keine Zeit für Predigten. Bleib bei uns!", "%s, bleibt bei mir! Das Licht ist schon da.", "*stößt die Hand rasch vor, sodass ein kurzer Lichtimpuls aufflammt.*", "*fängt den eigenen Atem wieder ein, während das Licht schon wirkt.*" }, },
    HOLY_FIRE = { gruppe = { "Wenn Licht brennt, bleibt keine Lüge verborgen.", "Dieses Feuer kommt nicht aus der Esse. Es antwortet auf meinen Glauben.", "*schließt die Faust um einen hellen Funken und wirft ihn mit einer Öffnung der Hand fort.*", "*blickt unbewegt auf die Spur aus goldenem Feuer.*" }, ziel = { "Wenn Licht brennt, bleibt keine Lüge verborgen.", "%s, das Licht hat heute eine brennende Antwort für Euch.", "*schließt die Faust um einen hellen Funken und wirft ihn mit einer Öffnung der Hand fort.*", "*blickt unbewegt auf die Spur aus goldenem Feuer.*" }, },
    HOLY_NOVA = { gruppe = { "Lasst uns die Dunkelheit gemeinsam zurückdrängen.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    PRAYER_OF_HEALING = { gruppe = { "Für jeden von euch ein Atemzug Hoffnung.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    ABOLISH_DISEASE = { gruppe = { "Diese Krankheit hat hier kein Bleiberecht.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Diese Krankheit hat hier kein Bleiberecht.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    GREATER_HEAL = { gruppe = { "Halte durch. Ich brauche einen Moment und du bekommst viele zurück.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Halte durch. Ich brauche einen Moment und du bekommst viele zurück.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    LIGHTWELL = { gruppe = { "Ein stiller Ort, an dem Mut wieder Wurzeln schlägt.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    LIGHTWELL_RENEW = { gruppe = { "Ein Tropfen Hoffnung lässt sich weiterreichen.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Ein Tropfen Hoffnung lässt sich weiterreichen.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    PRAYER_OF_MENDING = { gruppe = { "Möge mein Segen den Nächsten finden, der ihn braucht.", "Selbst im schlimmsten Sturm findet ein Herz den Takt zurück.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, ziel = { "Möge mein Segen den Nächsten finden, der ihn braucht.", "Haltet durch, %s. Hier endet Eure Geschichte noch nicht.", "*hebt die offenen Hände in einem stillen Gebet*", "*lässt Licht zwischen den Fingern aufscheinen*" }, },
    SHADOW_WORD_PAIN = { gruppe = { "Ein einziges Wort. Der Rest ist eure Erinnerung daran.", "Eine Silbe genügt, um einen Gedanken mit Dornen zu umgeben.", "*senkt das Kinn, während ein dunkles Zeichen über der Handfläche entsteht.*", "*entlässt ein raues Flüstern, das keinen sichtbaren Ursprung hat.*" }, ziel = { "Ein einziges Wort. Der Rest ist eure Erinnerung daran.", "%s, dieses Wort wird Euch länger begleiten, als Ihr möchtet.", "*senkt das Kinn, während ein dunkles Zeichen über der Handfläche entsteht.*", "*entlässt ein raues Flüstern, das keinen sichtbaren Ursprung hat.*" }, },
    FADE = { gruppe = { "Man muss nicht verschwinden, um übersehen zu werden.", "Die Dunkelheit verrät viel, wenn man ihr zuhört.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, },
    HEX_OF_WEAKNESS = { gruppe = { "Stärke ist eine Geschichte, die man euch zu oft erzählt hat.", "Die Dunkelheit verrät viel, wenn man ihr zuhört.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, ziel = { "Stärke ist eine Geschichte, die man euch zu oft erzählt hat.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, },
    MIND_BLAST = { gruppe = { "Manche Türen öffnet man besser nicht. Diese schon.", "Eure Gedanken sind eine Festung mit einem erstaunlich schwachen Tor.", "*presst zwei Finger an die Schläfe und stößt die Hand nach vorn.*", "*lässt eine unsichtbare Erschütterung durch die Luft laufen.*" }, ziel = { "Manche Türen öffnet man besser nicht. Diese schon.", "%s, haltet Eure Gedanken besser fest.", "*presst zwei Finger an die Schläfe und stößt die Hand nach vorn.*", "*lässt eine unsichtbare Erschütterung durch die Luft laufen.*" }, },
    TOUCH_OF_WEAKNESS = { gruppe = { "Hinter jeder Berührung wartet eine zweite Absicht.", "Die Dunkelheit verrät viel, wenn man ihr zuhört.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, },
    PSYCHIC_SCREAM = { gruppe = { "Die Angst hat eine Stimme. Ich leihe ihr meine.", "Wenn der Verstand flieht, braucht der Körper keinen Befehl mehr.", "*reißt die Arme auseinander, als zerbreche etwas Unsichtbares zwischen ihnen.*", "*stößt einen tonlosen Schrei aus, der die Luft erzittern lässt.*" }, },
    DARK_SACRIFICE = { gruppe = { "Ein Preis muss bezahlt werden. Heute kenne ich den Namen des Schuldners.", "Die Dunkelheit verrät viel, wenn man ihr zuhört.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, },
    DEVOURING_PLAGUE = { gruppe = { "Euer Hochmut hat Wurzeln. Ich ziehe daran.", "Die Dunkelheit verrät viel, wenn man ihr zuhört.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, ziel = { "Euer Hochmut hat Wurzeln. Ich ziehe daran.", "Euer nächster Gedanke wird vorsichtiger sein, %s.", "*folgt mit dem Blick einem unsichtbaren Schatten*", "*flüstert eine Silbe, die im Raum zu verblassen scheint*" }, },
